// Act VII's text, from the design's key tables to src/i18n/text7.js (run again whenever a table changes; the two
// proofreaders edit the tables, never the generated file). node tools/text7-import.mjs
import { readFileSync, writeFileSync } from 'node:fs';
// (the story part is read last: where both give a key, the story's wording stands)
const parts = [['docs/act7-design/50-text-extra.md', '## Extra text keys'], ['docs/act7-design/30-mechanics-progression.md', '## New text keys'], ['docs/act7-design/10-story.md', '## Every new text key']];
const out = new Map(), dup = [];
const strip = (s) => { s = s.trim(); if (/^«.*»$/.test(s) && !s.slice(1, -1).includes('«')) s = s.slice(1, -1); if (/^".*"$/.test(s) && !s.slice(1, -1).includes('"')) s = s.slice(1, -1); return s.replace(/\\\|/g, '|').replace(/<br\s*\/?>/g, '\n'); };
for (const [f, head] of parts) {
  let on = false; const seen = new Map();
  for (const line of readFileSync(f, 'utf8').split('\n')) {
    if (line.startsWith('## ')) on = line.startsWith(head);
    if (!on || !line.startsWith('|')) continue;
    const c = line.split(/(?<!\\)\|/).slice(1, -1).map((x) => x.trim());
    const ki = c.findIndex((x) => /^`[A-Za-z0-9_@-]+\.[A-Za-z0-9_.@-]+`$/.test(x));
    if (ki < 0 || ki > 1 || c.length < ki + 3) continue;
    const key = c[ki].slice(1, -1), el = strip(c[ki + 1]), en = strip(c[ki + 2]);
    if (!el || !en || /^[-: ]+$/.test(el)) continue;
    if (seen.has(key) && seen.get(key) !== el + en) dup.push(f.slice(17, 19) + ':' + key);
    seen.set(key, el + en);
    out.set(key, [el, en]);
  }
}
const q = (s) => "'" + s.replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\n/g, '\\n') + "'";
const body = [...out].map(([k, [el, en]]) => `  ${q(k)}: [${q(el)}, ${q(en)}]`).join(',\n');
writeFileSync('src/i18n/text7.js', `// Act VII's strings: GENERATED by tools/text7-import.mjs from docs/act7-design (10-story, 30-mechanics-progression).\n// Do not edit by hand: change the design's table and run the tool. key -> [Greek, English]\nexport const TEXT7 = {\n${body}\n};\n`);
console.log(out.size + ' keys', dup.length ? 'CONFLICTING: ' + dup.join(', ') : '');
